async function refreshList(lorebookName, isGlobal) {
  // In refreshList() function, call clearSelectedEntries() before reloading
  clearSelectedEntries(lorebookName);

  const parentDoc = window.parent.document;
  const $entriesWrapper = $(`.lorebook-entries-wrapper[data-lorebook-name="${lorebookName}"]`, parentDoc);
  if ($entriesWrapper.is(':visible')) {
    await loadLorebookEntries(lorebookName, $entriesWrapper, isGlobal);
  }
}

export function bindEventListeners() {
  const parentDoc = window.parent.document;
  const $panel = $(`#${LOREBOOK_PANEL_ID}`, parentDoc);
  const $editorPanel = $(`#${LOREBOOK_EDITOR_PANEL_ID}`, parentDoc);

  // --- Layout Debugger ---
  $(parentDoc).on('click', '#layout-debugger-button', () => {
    console.clear();
    console.log('%c--- Layout Debugger Initialized ---', 'color: #ff4d4d; font-weight: bold; font-size: 1.2em;');

    const $modal = $('#lorebook-import-modal', parentDoc);
    const $mainPanel = $(`#${LOREBOOK_PANEL_ID}`, parentDoc);

    if (!$modal.length) {
      console.error('DEBUGGER: Import modal (#lorebook-import-modal) not found in DOM.');
      return;
    }
    if (!$mainPanel.length) {
      console.error('DEBUGGER: Main panel (#enhanced-lorebook-panel) not found in DOM.');
      return;
    }

    console.log('%c1. Modal Parent Hierarchy Trace:', 'color: #4d94ff; font-weight: bold;');
    let current = $modal.get(0);
    const path = [];
    while (current && current.tagName !== 'BODY') {
      const { tagName, id, className } = current;
      const style = window.getComputedStyle(current);
      const position = style.getPropertyValue('position');
      const transform = style.getPropertyValue('transform');
      const filter = style.getPropertyValue('filter');
      const perspective = style.getPropertyValue('perspective');

      path.push({
        element: tagName.toLowerCase() + (id ? `#${id}` : '') + (className ? `.${className.split(' ').join('.')}` : ''),
        position,
        transform: transform !== 'none' ? transform : 'default',
        filter: filter !== 'none' ? filter : 'default',
        perspective: perspective !== 'none' ? perspective : 'default',
      });
      current = current.parentElement;
    }
    console.table(path);
    if (path.some(p => p.transform !== 'default' || p.filter !== 'default' || p.perspective !== 'default')) {
      console.warn(
        'DEBUGGER: Found a parent with transform, filter, or perspective. This is likely trapping the `position: fixed` modal and causing the layout issue.',
      );
    } else {
      console.log(
        'DEBUGGER: No parent element seems to be creating a new stacking context. The issue might be elsewhere.',
      );
    }

    console.log('%c2. Computed Styles Comparison:', 'color: #4d94ff; font-weight: bold;');
    const getStyles = (elem, name) => {
      const style = window.getComputedStyle(elem);
      return {
        element: name,
        display: style.getPropertyValue('display'),
        position: style.getPropertyValue('position'),
        top: style.getPropertyValue('top'),
        left: style.getPropertyValue('left'),
        width: style.getPropertyValue('width'),
        height: style.getPropertyValue('height'),
        zIndex: style.getPropertyValue('z-index'),
        overflow: style.getPropertyValue('overflow'),
      };
    };
    console.table([
      getStyles($modal.get(0), '#lorebook-import-modal'),
      getStyles($mainPanel.get(0), '#enhanced-lorebook-panel'),
    ]);

    console.log('%c--- Debug Report Complete ---', 'color: #ff4d4d; font-weight: bold; font-size: 1.2em;');
    alert('调试报告已输出到浏览器开发者控制台 (按 F12 打开)。请将Console标签页下的内容截图或复制给开发者。');
  });

  // Mobile long-press tooltip logic
  if (isMobile()) {
    let pressTimer;
    let lastTouchX = 0;
    let lastTouchY = 0;

    $panel.on('touchstart', '[title]', function (e) {
      const $target = $(this);
      const title = $target.attr('title');
      if (!title) return;

      lastTouchX = e.originalEvent.touches.clientX;
      lastTouchY = e.originalEvent.touches.clientY;

      pressTimer = setTimeout(() => {
        const $tooltip = $(`#${MOBILE_TOOLTIP_ID}`, parentDoc);
        $tooltip.text(title).css({ top: '-9999px', left: '-9999px' }).show(); // Show it off-screen first to get dimensions

        const targetRect = $target.get(0).getBoundingClientRect();
        const tooltipNode = $tooltip.get(0);
        const tooltipWidth = tooltipNode.offsetWidth;
        const tooltipHeight = tooltipNode.offsetHeight;
        const windowWidth = window.parent.innerWidth;

        // Default position: above the target, horizontally centered
        let top = targetRect.top - tooltipHeight - 10; // 10px gap
        let left = targetRect.left + targetRect.width / 2 - tooltipWidth / 2;

        // Boundary checks
        if (top < 5) {
          // If it goes off the top edge
          top = targetRect.bottom + 10; // Place it below the target
        }
        if (left < 5) {
          // If it goes off the left edge
          left = 5;
        }
        if (left + tooltipWidth > windowWidth - 5) {
          // If it goes off the right edge
          left = windowWidth - tooltipWidth - 5;
        }

        $tooltip.css({
          top: `${top}px`,
          left: `${left}px`,
          transform: 'none', // Reset transform as we now calculate the centered position manually
        });
      }, 500); // 500ms for long press
    });

    $panel.on('touchend touchcancel', '[title]', function () {
      clearTimeout(pressTimer);
      $(`#${MOBILE_TOOLTIP_ID}`, parentDoc).hide();
    });

    $panel.on('touchmove', '[title]', function (e) {
      const touch = e.originalEvent.touches;
      // If finger moves too far, cancel the long press
      if (Math.abs(touch.clientX - lastTouchX) > 10 || Math.abs(touch.clientY - lastTouchY) > 10) {
        clearTimeout(pressTimer);
        $(`#${MOBILE_TOOLTIP_ID}`, parentDoc).hide();
      }
    });
  }

  // Double-click header to show debug info
  const toggleDebug = $elem => {
    $elem.find('.debug-info').toggle();
  };
  $panel.find('.panel-header h4').on('dblclick', () => toggleDebug($panel));
  $editorPanel.find('.modal-header h4').on('dblclick', function () {
    toggleDebug($(this).closest('.lorebook-modal-content'));
  });

  // Main panel button and close button
  $(parentDoc)
    .off(`click.${LOREBOOK_BUTTON_ID}`)
    .on(`click.${LOREBOOK_BUTTON_ID}`, `#${LOREBOOK_BUTTON_ID}`, event => {
      event.preventDefault();
      toggleLorebookPanel();
    });
  $panel.off('click.lorebookClose').on('click.lorebookClose', '.close-button', toggleLorebookPanel);

  // Tab switching
  $panel.off('click.lorebookTabs').on('click.lorebookTabs', '.tab-button', function () {
    const tabId = $(this).attr('id');
    if (tabId && !$(this).hasClass(ACTIVE_TAB_CLASS)) {
      switchTab(tabId);
    }
  });

  // Event delegation for all entry and title bar interactions
  $panel.on('click change input', `[data-action]`, async function (e) {
    e.stopPropagation();
    const $target = $(e.target);
    const $actionTarget = $target.closest('[data-action]');
    if (!$actionTarget.length) return;

    const action = $actionTarget.data('action');
    const $title = $target.closest('.lorebook-title');
    const $item = $target.closest(`.${LOREBOOK_ENTRY_CLASS}`);

    const isTitleAction = $title.length > 0 && !$item.length;
    const isSelectorAction = $target.closest('#global-lorebook-selector').length > 0;

    if (isSelectorAction) {
      const $listContainer = $panel.find(`#${GLOBAL_LOREBOOK_LIST_CONTAINER_ID}`);

      if (action === 'toggle-global-lorebook') {
        const lorebookName = $actionTarget.data('lorebook-name');
        const wasActive = $actionTarget.hasClass('active');

        // Optimistic UI update for the tag
        $actionTarget.toggleClass('active');

        // API call, then update the list below
        toggleGlobalLorebook(lorebookName)
          .then(() => {
            if (wasActive) {
              // If it was active, now it's not. Just remove it from the list below.
              const $title = $listContainer.find(`.lorebook-title[data-lorebook-name="${lorebookName}"]`);
              const $wrapper = $listContainer.find(`.lorebook-entries-wrapper[data-lorebook-name="${lorebookName}"]`);
              const $divider = $title.next('.lorebook-divider');
              $title.remove();
              $wrapper.remove();
              $divider.remove();
            } else {
              // If it was inactive, now it's active. Use the new lightweight function.
              addGlobalLorebookToList($listContainer, lorebookName);
            }
          })
          .catch(() => {
            // On failure, revert the optimistic UI update
            $actionTarget.toggleClass('active');
          });
      } else if (action === 'unpin-global-lorebook') {
        const $tag = $actionTarget.closest('.lorebook-tag');
        const lorebookName = $tag.data('lorebook-name');

        // Optimistic UI update
        $tag.remove();
        const $header = $panel.find('.global-lorebook-selector-header');
        if ($header.length) {
          const currentCount = parseInt($header.text().match(/\d+/), 10);
          $header.text(`常驻世界书 (${currentCount - 1})`);
        }

        // Remove from the list below
        const $title = $listContainer.find(`.lorebook-title[data-lorebook-name="${lorebookName}"]`);
        const $wrapper = $listContainer.find(`.lorebook-entries-wrapper[data-lorebook-name="${lorebookName}"]`);
        const $divider = $title.next('.lorebook-divider');
        $title.remove();
        $wrapper.remove();
        $divider.remove();

        // API call and localStorage update in background
        disableGlobalLorebook(lorebookName);
        let pinnedBooks = getPinnedBooks();
        pinnedBooks = pinnedBooks.filter(b => b !== lorebookName);
        savePinnedBooks(pinnedBooks);
      } else if (action === 'pin-global-lorebook') {
        const lorebookName = $actionTarget.data('lorebook-name');

        // Update state
        const pinnedBooks = getPinnedBooks();
        if (!pinnedBooks.includes(lorebookName)) {
          pinnedBooks.push(lorebookName);
          savePinnedBooks(pinnedBooks);
        }

        // UI update: clear search and re-render only the selector
        $('#add-worldbook-search-input', parentDoc).val('');
        $('.add-worldbook-results', parentDoc).empty().hide();
        renderGlobalLorebookSelector();
      } else if (action === 'toggle-preset-dropdown') {
        const $dropdown = $target.closest('.preset-dropdown-container').find('.preset-dropdown-menu');
        $dropdown.toggle();
      } else if (action === 'save-preset') {
        const name = prompt('请输入预设名称：');
        if (name) {
          if (await createPresetFromCurrentState(name)) {
            alert(`预设 "${name}" 保存成功！`);
            // 刷新下拉菜单
            renderGlobalLorebookSelector();
            // 重新打开下拉菜单
            setTimeout(() => {
              $('.preset-dropdown-menu', parentDoc).show();
            }, 100);
          } else {
            alert('保存预设失败。');
          }
        }
      } else if (action === 'apply-preset') {
        const name = $target.data('preset-name');
        if (confirm(`确定要应用预设 "${name}" 吗？\n这将覆盖当前的常驻世界书列表和启用状态。`)) {
          if (await applyPreset(name)) {
            alert(`预设 "${name}" 已应用！`);
          } else {
            alert('应用预设失败。');
          }
        }
      } else if (action === 'delete-preset') {
        const name = $target.data('preset-name');
        if (confirm(`确定要删除预设 "${name}" 吗？`)) {
          if (await deletePreset(name)) {
            // 重新打开下拉菜单
            setTimeout(() => {
              $('.preset-dropdown-menu', parentDoc).show();
            }, 100);
          } else {
            alert('删除预设失败。');
          }
        }
      }
      return;
    }

    if (action === 'import-worldbook') {
      (async () => {
        try {
          const { filename, content } = await openFilePickerAndRead();
          const response = await importWorldbookSafe(filename, content);
          if (response.ok) {
            alert(`世界书 "${filename}" 导入成功！`);
            // 刷新角色世界书列表以显示新导入的书
            await updateBoundLorebooksList($panel.find(`#${LOREBOOK_LIST_CONTAINER_ID}`), true);
          } else {
            throw new Error(`导入失败: ${response.statusText}`);
          }
        } catch (error) {
          console.error('[调试] 导入世界书时出错:', error);
          if (error.message !== '未选择任何文件。') {
            alert(`导入失败: ${error.message}`);
          }
        }
      })();
      return;
    }

    if (action === 'set-as-char-lorebook') {
      const lorebookNames = [];
      $panel.find(`#${LOREBOOK_LIST_CONTAINER_ID} .lorebook-title`).each(function () {
        lorebookNames.push($(this).data('lorebook-name'));
      });

      if (lorebookNames.length === 0) {
        alert('当前没有显示任何世界书，无法设置。');
        return;
      }

      if (
        confirm(
          `确定要将当前显示的 ${lorebookNames.length} 个世界书（${lorebookNames.join(', ')}）设置为角色的绑定世界书吗？这会覆盖角色当前已绑定的世界书。`,
        )
      ) {
        (async () => {
          try {
            // rebindCharWorldbooks 需要一个 { primary: string, additional: string[] } 格式的对象
            // 我们将列表中的第一个设为 primary，其余的设为 additional
            const charWorldbooks = {
              primary: lorebookNames[0] || null,
              additional: lorebookNames.slice(1),
            };
            await rebindCharWorldbooksSafe(charWorldbooks);
            alert('成功将显示的世界书设置为角色世界书！');
            // 刷新一下，以确认UI与后台数据同步
            await updateBoundLorebooksList($panel.find(`#${LOREBOOK_LIST_CONTAINER_ID}`), true);
          } catch (error) {
            console.error('设置角色世界书时出错:', error);
            alert('设置角色世界书时出错，请查看控制台了解详情。');
          }
        })();
      }
      return;
    }

    if (action === 'set-as-chat-lorebook') {
      const lorebookNames = [];
      $panel.find(`#${LOREBOOK_LIST_CONTAINER_ID} .lorebook-title`).each(function () {
        lorebookNames.push($(this).data('lorebook-name'));
      });

      if (lorebookNames.length === 0) {
        alert('当前没有显示任何世界书，无法设置。');
        return;
      }

      if (lorebookNames.length > 1) {
        alert('当前显示了多个世界书，请确保只显示一个世界书后再进行此操作。');
        return;
      }

      const worldbookName = lorebookNames[0];
      if (confirm(`确定要将当前显示的世界书 "${worldbookName}" 设置为聊天世界书吗？`)) {
        (async () => {
          try {
            await rebindChatWorldbookSafe(worldbookName);
            alert(`成功将世界书 "${worldbookName}" 设置为聊天世界书！`);
          } catch (error) {
            console.error('设置聊天世界书时出错:', error);
            alert('设置聊天世界书时出错，请查看控制台了解详情。');
          }
        })();
      }
      return;
    }

    if (action === 'export-worldbook') {
      const lorebookNames = [];
      // 修正：判断当前激活的标签页，以确定正确的导出范围
      const activeTabId = $panel.find('.tab-button.active-tab').attr('id');
      let listContainerId;

      if (activeTabId === 'character-lorebook-tab') {
        listContainerId = `#${LOREBOOK_LIST_CONTAINER_ID}`;
      } else {
        listContainerId = `#${GLOBAL_LOREBOOK_LIST_CONTAINER_ID}`;
      }

      // 使用动态的容器ID来查找世界书标题
      $panel.find(`${listContainerId} .lorebook-title`).each(function () {
        lorebookNames.push($(this).data('lorebook-name'));
      });

      if (lorebookNames.length > 0) {
        (async () => {
          for (const bookName of lorebookNames) {
            try {
              const entries = await getWorldbookSafe(bookName);

              if (entries) {
                // 调用转换函数，将插件格式转换为酒馆原生格式
                const nativeWorldbook = convertPluginToNativeFormat(entries);

                // 序列化原生格式的对象
                const content = JSON.stringify(nativeWorldbook, null, 2); // 使用2个空格的缩进更常见
                const filename = `${bookName}.json`;

                triggerDownload(filename, content);
              } else {
                console.error(`[调试] 获取 '${bookName}' 的内容失败，返回值为 null 或 undefined。`);
              }
            } catch (error) {
              console.error(`[调试] 导出世界书 '${bookName}' 时发生错误:`, error);
              alert(`导出世界书 '${bookName}' 失败，请查看控制台了解详情。`);
            }
          }
          alert(`已处理 ${lorebookNames.length} 个世界书的导出请求。请注意浏览器的下载提示。`);
        })();
      } else {
        alert('[调试] 在当前标签页未找到可导出的世界书。');
      }
      return;
    }

    if (action === 'create-worldbook') {
      const worldbookName = prompt('请输入新的世界书名称：');
      if (worldbookName) {
        try {
          await createWorldbookSafe(worldbookName);
          alert(`世界书 "${worldbookName}" 创建成功！\n你现在可以在“替换显示”的搜索框中找到它并进行编辑。`);
          // 不刷新列表，因为新书未绑定
        } catch (error) {
          alert(`创建世界书失败: ${error.message}`);
        }
      }
      return;
    }

    if (action === 'delete-worldbook') {
      const $listContainer = $panel.find(`#${LOREBOOK_LIST_CONTAINER_ID}`);
      const $displayedTitle = $listContainer.find('.lorebook-title');

      if ($displayedTitle.length !== 1) {
        alert('操作失败：当前没有或有多个世界书正在显示。请确保只加载了一个世界书。');
        return;
      }

      const worldbookName = $displayedTitle.data('lorebook-name');
      if (confirm(`确定要删除当前显示的世界书 "${worldbookName}" 吗？此操作不可撤销。`)) {
        try {
          await deleteWorldbookSafe(worldbookName);
          alert(`世界书 "${worldbookName}" 删除成功！`);
          // 删除后刷新回角色绑定的世界书列表
          await updateBoundLorebooksList($listContainer, true);
        } catch (error) {
          alert(`删除世界书失败: ${error.message}`);
        }
      }
      return;
    }

    if (action === 'rename-worldbook') {
      const $listContainer = $panel.find(`#${LOREBOOK_LIST_CONTAINER_ID}`);
      const $displayedTitle = $listContainer.find('.lorebook-title');

      if ($displayedTitle.length !== 1) {
        alert('操作失败：当前没有或有多个世界书正在显示。请确保只加载了一个世界书。');
        return;
      }

      const oldName = $displayedTitle.data('lorebook-name');
      const newName = prompt(`请输入新的世界书名称：`, oldName);
      if (newName && newName !== oldName) {
        try {
          await renameWorldbookSafe(oldName, newName);
          alert(`世界书 "${oldName}" 已成功重命名为 "${newName}"！`);
          // 局部更新UI，避免刷新
          const $wrapper = $listContainer.find(`.lorebook-entries-wrapper[data-lorebook-name="${oldName}"]`);
          $displayedTitle.find('.lorebook-title-text').text(newName);
          $displayedTitle.attr('data-lorebook-name', newName).data('lorebook-name', newName);
          $wrapper.attr('data-lorebook-name', newName).data('lorebook-name', newName);
          await loadLorebookEntries(newName, $wrapper, false);
        } catch (error) {
          alert(`重命名世界书失败: ${error.message}`);
        }
      }
      return;
    }

    if (action === 'replace-character-lorebook') {
      const lorebookName = $actionTarget.data('lorebook-name');
      const $listContainer = $panel.find(`#${LOREBOOK_LIST_CONTAINER_ID}`);

      // 清空除了搜索栏之外的所有内容
      $listContainer.find('> *:not(.global-lorebook-adder)').remove();
      $listContainer.append('<p>加载中...</p>');

      // 异步加载新的世界书
      setTimeout(async () => {
        try {
          $listContainer.find('p').remove(); // 移除“加载中”
          const $lorebookTitle = createLorebookTitleSection(lorebookName, false);
          $lorebookTitle.attr('data-lorebook-name', lorebookName);
          $listContainer.append($lorebookTitle);

          const $entriesWrapper = $('<div></div>')
            .addClass('lorebook-entries-wrapper')
            .attr('data-lorebook-name', lorebookName);
          $listContainer.append($entriesWrapper);

          await loadLorebookEntries(lorebookName, $entriesWrapper, false);
          updateHeaderCheckboxState(lorebookName, false);
        } catch (error) {
          console.error(`替换并加载世界书 ${lorebookName} 时出错:`, error);
          $listContainer.append('<p>加载世界书失败。</p>');
        }
      }, 10);

      // 清空搜索框并隐藏结果
      $('#character-worldbook-search-input', parentDoc).val('');
      $('#character-worldbook-search-results', parentDoc).empty().hide();
      return;
    }

    if (isTitleAction) {
      const lorebookName = $title.data('lorebook-name');
      const isGlobal = $title.data('is-global');

      switch (action) {
        case 'set-filter': {
          const filterType = $target.data('filter-type');
          const value = $target.prop('checked');

          console.log(`  - Lorebook: ${lorebookName} (isGlobal: ${isGlobal})`);
          console.log(`  - Filter Type: ${filterType}`);
          console.log(`  - Value: ${value}`);

          if (!lorebookName) {
            console.error('[DEBUG] 关键错误: lorebookName 未获取到！检查 .lorebook-title 的 data-lorebook-name 属性。');
          }

          setActiveFilter(lorebookName, filterType, value);

          // Refresh UI to reflect filter state
          const $dropdown = $target.closest('.filter-dropdown');
          const filters = getActiveFilters(lorebookName);
          $dropdown.find('input[type="checkbox"]').each(function () {
            const $cb = $(this);
            const type = $cb.data('filter-type');
            $cb.prop('checked', !!filters[type]);
          });

          // Reload the entries list
          refreshList(lorebookName, isGlobal);
          break;
        }
        case 'open-optimizer': {
          const $modal = $('#lorebook-optimize-modal', parentDoc);
          $modal.find('#lorebook-optimize-modal-title').text(`世界书优化工具: ${lorebookName}`);
          $modal.data('lorebook-name', lorebookName);
          $modal.data('is-global', isGlobal);
          $modal.css('display', 'flex');
          break;
        }
        case 'bulk-import': {
          const IMPORT_MODAL_ID = 'lorebook-import-modal';
          const $modal = $(`#${IMPORT_MODAL_ID}`, parentDoc);
          $modal.find(`#${IMPORT_MODAL_ID}-textarea`).val('');
          $modal.find(`#${IMPORT_MODAL_ID}-error`).hide();
          $modal.find(`#${IMPORT_MODAL_ID}-confirm`).text('确认导入').prop('disabled', false);
          $modal.find(`#${IMPORT_MODAL_ID}-header h4`).text(`批量导入到: ${lorebookName}`);
          $modal
            .find(`#${IMPORT_MODAL_ID}-confirm`)
            .off('click')
            .on('click', async () => {
              const success = await handleBulkImport(lorebookName, isGlobal);
              if (success) {
                refreshList(lorebookName, isGlobal);
              }
            });
          $modal.css('display', 'flex');
          break;
        }
        case 'copy-entries':
          await copySelectedEntries(lorebookName, isGlobal);
          break;
        case 'adjust-position':
          if (await adjustSelectedEntriesPosition(lorebookName, isGlobal)) {
            refreshList(lorebookName, isGlobal);
          }
          break;
        case 'delete-entries':
          if (await deleteSelectedEntries(lorebookName, isGlobal)) {
            refreshList(lorebookName, isGlobal);
          }
          break;
        case 'add-entry':
          if (await createNewLorebookEntry(lorebookName, isGlobal)) {
            refreshList(lorebookName, isGlobal);
          }
          break;
        case 'invert': {
          const field = $target.closest('[data-field]').data('field');
          const title = $target.closest('[title]').attr('title');
          const message = `确定要${title}吗？`;
          if (await batchUpdateEntries(lorebookName, isGlobal, { invert: field }, message)) {
            refreshList(lorebookName, isGlobal);
          }
          break;
        }
        case 'execute-batch-toggle': {
          console.log('[批量操作] 开始执行批量开关操作');
          const $dropdown = $target.closest('.batch-toggle-dropdown');
          const operation = $dropdown.find('input[name="batch-operation"]:checked').val();
          const selectedFields = $dropdown
            .find('.batch-toggle-checkbox-group input:checked')
            .map(function () {
              return $(this).val();
            })
            .get();

          console.log('[批量操作] 操作类型:', operation, '选中字段:', selectedFields);

          if (selectedFields.length === 0) {
            window.toastr?.warning('请至少选择一个操作字段');
            break;
          }

          const fieldNames = {
            enabled: '启用状态',
            'strategy.type': '激活模式',
            'recursion.prevent_outgoing': '防止递归',
            'recursion.prevent_incoming': '排除递归',
          };
          const operationNames = { enable: '全开', disable: '全关', invert: '反转' };
          const fieldList = selectedFields.map(f => fieldNames[f]).join('、');
          const message = `确定要对 ${fieldList} 进行${operationNames[operation]}操作吗？`;

          if (!confirm(message)) {
            break;
          }

          let successCount = 0;
          for (const field of selectedFields) {
            let updateData;
            if (operation === 'invert') {
              updateData = { invert: field };
              console.log('[批量操作] 反转字段:', field);
            } else if (operation === 'enable') {
              if (field === 'enabled') {
                updateData = { [field]: true };
              } else if (field === 'strategy.type') {
                updateData = { [field]: 'constant' };
              } else if (field.startsWith('recursion.')) {
                updateData = { [field]: true };
              }
              console.log('[批量操作] 全开字段:', field, '更新数据:', updateData);
            } else if (operation === 'disable') {
              if (field === 'enabled') {
                updateData = { [field]: false };
              } else if (field === 'strategy.type') {
                updateData = { [field]: 'selective' };
              } else if (field.startsWith('recursion.')) {
                updateData = { [field]: false };
              }
              console.log('[批量操作] 全关字段:', field, '更新数据:', updateData);
            }

            if (await batchUpdateEntries(lorebookName, isGlobal, updateData, null)) {
              successCount++;
            }
          }

          if (successCount > 0) {
            $('.lorebook-batch-toggle-container', parentDoc).removeClass('active');
            refreshList(lorebookName, isGlobal);
          }
          break;
        }
        case 'select-all': {
          // 从按钮获取属性，优先使用按钮自己的属性
          // 注意：应该从 $actionTarget（button元素）获取，而不是 $target（可能是 i 图标）
          const buttonLorebookName = $actionTarget.attr('data-lorebook-name') || lorebookName;
          // 修复：正确处理字符串到布尔值的转换
          const buttonIsGlobalAttr = $actionTarget.attr('data-is-global');
          const buttonIsGlobal = buttonIsGlobalAttr !== undefined ? buttonIsGlobalAttr === 'true' : isGlobal;

          // 构建正确的选择器
          const containerSelector = buttonIsGlobal
            ? `.lorebook-entries-container[data-lorebook-name="${buttonLorebookName}"][data-is-global="true"]`
            : `.lorebook-entries-container[data-lorebook-name="${buttonLorebookName}"]:not([data-is-global="true"])`;

          const $container = $(containerSelector, parentDoc);

          if ($container.length) {
            const $allCheckboxes = $container.find(`.${LOREBOOK_ENTRY_CHECKBOX_CLASS}`);
            const $checkedCheckboxes = $allCheckboxes.filter(':checked');
            const shouldSelectAll = $checkedCheckboxes.length < $allCheckboxes.length;

            toggleAllEntries(buttonLorebookName, buttonIsGlobal, shouldSelectAll);
          }
          break;
        }
      }
      return;
    }

    if (!$item.length || !action) return;

    const lorebookName = $item.data('entry-lorebook');
    const numericUid = ensureNumericUID($item.data('entry-uid'));
    const isGlobal = $item.closest('.lorebook-entries-container').attr('data-is-global') === 'true';

    switch (action) {
      case 'open-editor': {
        if ($(e.target).hasClass('entry-header')) {
          showEntryEditor(lorebookName, numericUid, isGlobal);
        }
        break;
      }
      case 'expand': {
        const isExpanded = $item.attr('data-expanded') === 'true';
        const newExpandedState = !isExpanded;

        // 保存展开状态到state
        toggleEntryExpanded(lorebookName, numericUid, newExpandedState);

        $item.attr('data-expanded', newExpandedState);

        // 【修复】处理展开/折叠状态的高度样式
        if (newExpandedState) {
          // 展开时：设置为 auto 高度，覆盖内联固定高度
          $item.css('height', 'auto');
        } else {
          // 折叠时：恢复为固定高度（从虚拟滚动修复方案中获取）
          // 由于我们使用了内联样式，需要移除它以让CSS类控制高度
          $item.css('height', '');
        }

        $item.find('.entry-expand-area').slideToggle(200, () => {
          // 最终解决方案：在用户操作导致行高变化后，再调用refresh。
          const clusterize = virtualScrollers[lorebookName];
          if (clusterize) {
            clusterize.refresh(true);
          }
        });
        const $icon = $target.closest('.small-expand-button').find('i');
        $icon.toggleClass('fa-chevron-up fa-chevron-down');

        // 初始化token计数
        if (newExpandedState) {
          const $textarea = $item.find('.content-textarea');
          const content = $textarea.val() || '';
          const $counter = $item.find('.token-counter');
          $counter.text('计算中...');

          // 使用酒馆的真实tokenizer计算token数
          if (window.SillyTavern && window.SillyTavern.getTokenCountAsync) {
            window.SillyTavern.getTokenCountAsync(content)
              .then(tokenCount => {
                $counter.text(`${tokenCount} 词符`);
              })
              .catch(err => {
                console.warn('Token计数失败，使用字符数作为后备:', err);
                $counter.text(`${content.length} 字符`);
              });
          } else {
            // 后备方案：使用字符数
            $counter.text(`${content.length} 字符`);
          }
        }
        break;
      }

      case 'toggle-enabled': {
        const newState = $target.prop('checked');
        toggleEntryEnabled(lorebookName, numericUid, newState).then(success => {
          if (success) {
            $item.toggleClass('disabled-entry', !newState).attr('data-enabled', newState);
          } else {
            $target.prop('checked', !newState);
          }
        });
        break;
      }
      case 'edit-title':
        if (e.type === 'change') {
          saveEntryField(numericUid, lorebookName, 'name', $target.val());
        }
        break;
      case 'toggle-constant': {
        const isNowConstant = $target.prop('checked');
        $target
          .next('.mini-toggle-slider')
          .toggleClass('constant', isNowConstant)
          .toggleClass('keyword', !isNowConstant);
        saveEntryField(numericUid, lorebookName, 'strategy.type', isNowConstant ? 'constant' : 'selective');
        break;
      }
      case 'edit-position': {
        const newPosition = $target.val();
        const $depthInput = $item.find('[data-action="edit-depth"]');
        const needsDepth = newPosition === 'at_depth';
        $depthInput.prop('disabled', !needsDepth);
        $depthInput.closest('.depth-input-container').toggleClass('depth-disabled', !needsDepth);
        saveEntryField(numericUid, lorebookName, 'position.type', newPosition);
        break;
      }
      case 'edit-depth':
        if (e.type === 'change' && !$target.prop('disabled')) {
          saveEntryField(numericUid, lorebookName, 'position.depth', parseInt($target.val()));
        }
        break;
      case 'edit-order':
        if (e.type === 'change') {
          saveEntryField(numericUid, lorebookName, 'position.order', parseInt($target.val()));
        }
        break;
      case 'edit-prob':
        if (e.type === 'change') {
          saveEntryField(numericUid, lorebookName, 'probability', parseInt($target.val()));
        }
        break;
      case 'open-content-editor': {
        // 由于事件已在 item 上下文，可以直接获取 lorebookName 和 numericUid
        await showContentEditor(lorebookName, numericUid);
        break;
      }
      case 'select-entry': {
        // When checkbox is clicked, call toggleEntrySelection() with checked state
        const isSelected = $target.prop('checked');
        toggleEntrySelection(lorebookName, numericUid, isSelected);
        // Call updateHeaderCheckboxState() after state change
        updateHeaderCheckboxState(lorebookName, isGlobal);
        break;
      }
      case 'edit-content':
        if (e.type === 'change') {
          saveEntryField(numericUid, lorebookName, 'content', $target.val());
        }
        if (e.type === 'input') {
          const content = $target.val() || '';
          const $counter = $item.find('.token-counter');

          // 使用酒馆的真实tokenizer计算token数
          if (window.SillyTavern && window.SillyTavern.getTokenCountAsync) {
            window.SillyTavern.getTokenCountAsync(content)
              .then(tokenCount => {
                $counter.text(`${tokenCount} 词符`);
              })
              .catch(err => {
                console.warn('Token计数失败，使用字符数作为后备:', err);
                $counter.text(`${content.length} 字符`);
              });
          } else {
            // 后备方案：使用字符数
            $counter.text(`${content.length} 字符`);
          }
        }
        break;
      case 'edit-keys': {
        if (e.type === 'change') {
          const newKeywords = $target
            .val()
            .split(',')
            .map(k => k.trim())
            .filter(k => k);
          saveEntryField(numericUid, lorebookName, 'strategy.keys', newKeywords);
        }
        break;
      }
      case 'edit-keys-secondary': {
        if (e.type === 'change') {
          const newKeywords = $target
            .val()
            .split(',')
            .map(k => k.trim())
            .filter(k => k);
          saveEntryField(numericUid, lorebookName, 'strategy.keys_secondary.keys', newKeywords);
        }
        break;
      }
      case 'edit-keys-secondary-logic': {
        if (e.type === 'change') {
          saveEntryField(numericUid, lorebookName, 'strategy.keys_secondary.logic', $target.val());
        }
        break;
      }
      case 'toggle-prevent-outgoing':
        saveEntryField(numericUid, lorebookName, 'recursion.prevent_outgoing', $target.prop('checked'));
        break;
      case 'toggle-prevent-incoming':
        saveEntryField(numericUid, lorebookName, 'recursion.prevent_incoming', $target.prop('checked'));
        break;
      case 'toggle-delay-recursion':
        saveEntryField(numericUid, lorebookName, 'recursion.delay_until', $target.prop('checked'));
        break;
      case 'toggle-pinned':
        // 【功能修复】使用 localStorage 进行持久化
        (async () => {
          const isChecked = $target.prop('checked');

          // 步骤 1: 更新持久化存储
          if (isChecked) {
            addPinnedEntry(lorebookName, numericUid);
          } else {
            removePinnedEntry(lorebookName, numericUid);
          }

          // 步骤 2: 立即在前端内存状态中更新
          const entryToUpdate = allEntriesData[lorebookName].find(e => ensureNumericUID(e.uid) === numericUid);
          if (entryToUpdate) {
            entryToUpdate.pinned = isChecked;
          }

          // 步骤 3: 调用无感刷新，UI立即响应
          await updateVirtualScroll(lorebookName);

          // 注意：由于 localStorage 是同步操作，通常不会失败。
          // 即使失败（例如磁盘满了），错误也会在 settings.js 中被捕获并打印到控制台。
          // 因此，这里不再需要复杂的错误回滚逻辑。
        })();
        break;
    }
  });

  // Header checkbox
  $panel.off('change.headerCheckbox').on('change', '.header-checkbox', function (e) {
    e.stopPropagation();
    const $headerCheckbox = $(this);
    const lorebookName = $headerCheckbox.data('lorebook-name');
    const isGlobal = $headerCheckbox.data('is-global');
    const isChecked = $headerCheckbox.prop('checked');
    toggleAllEntries(lorebookName, isGlobal, isChecked);
    $headerCheckbox.prop('indeterminate', false);
  });

  // Global lorebook title click to expand/collapse
  $panel.off('click.lorebookTitleClick').on('click.lorebookTitleClick', '.lorebook-title-clickable', function (e) {
    e.stopPropagation();
    const $title = $(this);
    if (
      $(e.target).closest(
        '.lorebook-search-container, .lorebook-batch-action-button, .lorebook-delete-entries-button, .lorebook-add-entry-button, .sort-display-button, .lorebook-batch-toggle-container',
      ).length > 0
    ) {
      return;
    }
    const lorebookName = $title.attr('data-lorebook-name');
    const isLoaded = $title.attr('data-loaded') === 'true';
    const isExpanded = $title.attr('data-expanded') === 'true';
    const $entriesWrapper = $(`.lorebook-entries-wrapper[data-lorebook-name="${lorebookName}"]`);

    const toggleUI = state => {
      $title.attr('data-expanded', state);
      $title.find('.lorebook-expand-icon').toggleClass('fa-chevron-up', state).toggleClass('fa-chevron-down', !state);
      $entriesWrapper[state ? 'slideDown' : 'slideUp'](200);
    };

    if (isExpanded) {
      toggleUI(false);
    } else if (!isLoaded) {
      loadLorebookEntries(lorebookName, $entriesWrapper, true).then(success => {
        if (success) {
          $title.attr('data-loaded', 'true');
          toggleUI(true);
        } else {
          $entriesWrapper.html('<div class="no-entries-message">加载失败，请查看控制台</div>').show();
        }
      });
    } else {
      toggleUI(true);
    }
  });

  // Sort dropdown
  $panel.on('click', '.sort-display-button', function (e) {
    e.stopPropagation();
    $('.sort-dropdown', parentDoc).not($(this).siblings('.sort-dropdown')).hide();
    $(this).siblings('.sort-dropdown').toggle();
  });
  $panel.on('click', '.sort-dropdown li', function (e) {
    e.stopPropagation();
    const $li = $(this);
    const $container = $li.closest('.lorebook-title');
    const lorebookName = $container.find('.lorebook-search-input').data('lorebook-name');
    const isGlobal = $container.find('.lorebook-search-input').data('is-global');
    const sortBy = $li.data('sort-by');
    const sortDir = $li.data('sort-dir');

    lorebookSorts[lorebookName] = { by: sortBy, dir: sortDir };
    saveSortPreference();

    const $sortButton = $container.find('.sort-display-button');
    $sortButton.html(`${$li.text()} <i class="fa-solid fa-caret-down"></i>`);
    $li.siblings().removeClass('active');
    $li.addClass('active').closest('.sort-dropdown').hide();

    const $entriesWrapper = $(`.lorebook-entries-wrapper[data-lorebook-name="${lorebookName}"]`, parentDoc);
    if ($entriesWrapper.is(':visible')) {
      loadLorebookEntries(lorebookName, $entriesWrapper, isGlobal);
    }
  });
  $(parentDoc).on('click', () => {
    $panel.find('.sort-dropdown').hide();
    $panel.find('.lorebook-batch-toggle-container').removeClass('active');
  });

  // 点击外部关闭预设下拉菜单
  $(parentDoc).on('click', function (e) {
    if (!$(e.target).closest('.preset-dropdown-container').length) {
      $panel.find('.preset-dropdown-menu').hide();
    }
  });

  // Preset dropdown toggle
  $panel.on('click', '.preset-dropdown-button', function (e) {
    e.stopPropagation();
    const $menu = $(this).siblings('.preset-dropdown-menu');
    $('.preset-dropdown-menu', parentDoc).not($menu).hide(); // Close others
    $menu.toggle();
  });

  // Batch toggle dropdown
  $panel.on('click', '.batch-toggle-button', function (e) {
    e.stopPropagation();
    const $container = $(this).closest('.lorebook-batch-toggle-container');
    const wasActive = $container.hasClass('active');
    $('.lorebook-batch-toggle-container', parentDoc).removeClass('active');
    if (!wasActive) {
      $container.addClass('active');
    }
  });
  $panel.on('click', '.batch-toggle-dropdown', function (e) {
    e.stopPropagation();
  });

  // Filter dropdown - now using the same event handler as batch toggle
  // No need for separate event handlers as we're now using the same classes

  // Editor panel events
  $editorPanel.off('click.lorebookEditorClose').on('click', '.close-button, .cancel-button', function () {
    $editorPanel.find('#entry-edit-form').trigger('reset');
    $editorPanel.find('.save-button').text('保存').prop('disabled', false);
    $editorPanel.find('.debug-info').hide();
    $editorPanel.hide();
  });
  $editorPanel.off('submit.lorebookEditorForm').on('submit', '#entry-edit-form', async function (e) {
    e.preventDefault();
    const formData = Object.fromEntries(new FormData(this));
    formData.uid = ensureNumericUID(formData.uid);

    const $saveBtn = $(this).find('.save-button');
    $saveBtn.text('保存中...').prop('disabled', true);

    const { saveEditedEntry } = await import('./ui/editor.js');
    saveEditedEntry(formData)
      .then(result => {
        if (result.success) {
          $editorPanel.hide();
          const listContainerId = result.isGlobal
            ? `#${GLOBAL_LOREBOOK_LIST_CONTAINER_ID}`
            : `#${LOREBOOK_LIST_CONTAINER_ID}`;
          const $list = $panel.find(listContainerId);
          if (result.isGlobal) {
            const $wrapper = $(`.lorebook-entries-wrapper[data-lorebook-name="${formData.lorebook}"]`);
            loadLorebookEntries(formData.lorebook, $wrapper, true);
          } else {
            updateBoundLorebooksList($list, true);
          }
        } else {
          alert(`保存失败: ${result.message}`);
        }
      })
      .finally(() => {
        $saveBtn.text('保存').prop('disabled', false);
      });
  });
  $editorPanel.off('change.positionChange').on('change', '#entry-position', function () {
    toggleDepthFieldVisibility($(this).val());
  });
  $editorPanel.off('change.constantToggle').on('change', '#entry-constant', function () {
    const isChecked = $(this).prop('checked');
    const $slider = $(this).next('.constant-toggle-slider');
    $slider.css('background-color', isChecked ? '#2196F3' : '#4CAF50');
    const $container = $(this).closest('.constant-toggle-container');
    $container
      .find('.label-left')
      .css({ color: isChecked ? '#aaa' : '#fff', 'font-weight': isChecked ? 'normal' : 'bold' });
    $container
      .find('.label-right')
      .css({ color: isChecked ? '#fff' : '#aaa', 'font-weight': isChecked ? 'bold' : 'normal' });
  });
  $editorPanel.off('click.labelToggle').on('click', '.label-left, .label-right', function () {
    const $checkbox = $(this).closest('.constant-toggle-container').find('#entry-constant');
    $checkbox.prop('checked', $(this).hasClass('label-right')).trigger('change');
  });

  // Optimizer modal events
  // Delegated event handlers for dynamically created optimizer modals
  $(parentDoc).on('click', '#lorebook-optimize-modal .close-button', () => {
    $('#lorebook-optimize-modal', parentDoc).hide();
  });
  $(parentDoc).on('click', '#lorebook-reorder-modal .close-button', () => {
    $('#lorebook-reorder-modal', parentDoc).hide();
  });
  $(parentDoc).on('click', '#search-preview-modal .close-button', () => {
    $('#search-preview-modal', parentDoc).hide();
  });

  $(parentDoc).on('click', '#lorebook-optimize-modal [data-action]', async e => {
    const $target = $(e.currentTarget); // Use currentTarget for delegated events
    const action = $target.data('action');
    const $optimizeModal = $('#lorebook-optimize-modal', parentDoc);
    const lorebookName = $optimizeModal.data('lorebook-name');
    // 【修复】从modal读取时，data()返回的已经是布尔值，不需要再转换
    const isGlobal = $optimizeModal.data('is-global');
    let needsRefresh = false;

    switch (action) {
      case 'run-format-cleanup':
        needsRefresh = await runFormatCleanup(lorebookName, isGlobal);
        break;
      case 'run-keyword-fix':
        needsRefresh = await runKeywordFix(lorebookName, isGlobal);
        break;
      case 'run-reorder-entries-interactive':
        {
          const $container = $(`.lorebook-entries-container[data-lorebook-name="${lorebookName}"]`, parentDoc);
          const $selectedItems = $container
            .find(`.${LOREBOOK_ENTRY_CHECKBOX_CLASS}:checked`)
            .closest(`.${LOREBOOK_ENTRY_CLASS}`);
          if ($selectedItems.length < 2) {
            alert('请至少选择两个条目进行排序。');
            break;
          }
          const $reorderModal = $('#lorebook-reorder-modal', parentDoc);
          $reorderModal.css('display', 'flex');

          // No need for .off() with delegated events, but for confirm button it's safer
          $reorderModal
            .find('#confirm-reorder-button')
            .off('click')
            .on('click', async () => {
              const start = parseInt($('#reorder-start-number', $reorderModal).val(), 10);
              const step = parseInt($('#reorder-step-number', $reorderModal).val(), 10);
              const uidsInOrder = $selectedItems.map((i, el) => ensureNumericUID($(el).data('entry-uid'))).get();
              let modifiedCount = 0;
              await updateWorldbookWith(lorebookName, entries => {
                let hasChanges = false;
                const updatedEntries = [...entries];
                let currentOrder = start;
                uidsInOrder.forEach(uid => {
                  const entryIndex = updatedEntries.findIndex(entry => ensureNumericUID(entry.uid) === uid);
                  if (entryIndex !== -1) {
                    const originalEntry = updatedEntries[entryIndex];
                    if (_.get(originalEntry, 'position.order') !== currentOrder) {
                      const entryToUpdate = _.cloneDeep(originalEntry);
                      _.set(entryToUpdate, 'position.order', currentOrder);
                      updatedEntries[entryIndex] = entryToUpdate;
                      hasChanges = true;
                      modifiedCount++;
                    }
                    currentOrder += step;
                  }
                });
                return hasChanges ? updatedEntries : entries;
              });
              if (modifiedCount > 0) {
                alert(`成功为 ${modifiedCount} 个条目重新排序！`);
                refreshList(lorebookName, isGlobal);
              } else {
                alert('没有需要更新顺序的条目。');
              }
              $reorderModal.hide();
            });
        }
        break;
      case 'run-depth-optimization':
        needsRefresh = await runDepthOptimization(lorebookName, isGlobal);
        break;
      case 'run-cliche-cleanup':
        needsRefresh = await runClicheCleanup(lorebookName, isGlobal);
        break;
      case 'preview-global-search-replace':
        await previewGlobalSearchAndReplace(lorebookName, isGlobal);
        break;
      case 'execute-global-search-replace':
        needsRefresh = await executeGlobalSearchAndReplace(lorebookName, isGlobal);
        break;
    }

    if (needsRefresh) {
      await refreshList(lorebookName, isGlobal);
    }
  });
}

export function bindSearchEvents() {
  const parentDoc = window.parent.document;
  const $panel = $(`#${LOREBOOK_PANEL_ID}`, parentDoc);
  if (!$panel.length) return;

  // 筛选常驻世界书
  $panel.on('input', `#${GLOBAL_WORLDBOOK_SEARCH_ID}`, function () {
    const searchTerm = $(this).val().toLowerCase();
    const $tags = $(`#${GLOBAL_WORLDBOOK_TAGS_CONTAINER_ID} .lorebook-tag`, parentDoc);
    $tags.each(function () {
      const $tag = $(this);
      const lorebookName = $tag.data('lorebook-name').toLowerCase();
      $tag.toggle(lorebookName.includes(searchTerm));
    });
  });

  // 搜索并添加常驻世界书
  const debounceSearch = _.debounce(async (searchTerm, $input) => {
    const isCharacterSearch = $input.attr('id') === 'character-worldbook-search-input';
    const $resultsContainer = isCharacterSearch
      ? $('#character-worldbook-search-results', parentDoc)
      : $('.add-worldbook-results', parentDoc);

    if (searchTerm === null) {
      $resultsContainer.empty().hide();
      return;
    }

    const allBooks = await getWorldbookNamesSafe();
    let filteredBooks;

    if (isCharacterSearch) {
      // 角色书搜索：显示所有匹配的书
      filteredBooks = searchTerm ? allBooks.filter(b => b.toLowerCase().includes(searchTerm)) : allBooks;
    } else {
      // 全局书搜索：显示所有未固定的书
      const pinnedBooks = getPinnedBooks();
      filteredBooks = allBooks.filter(
        b => !pinnedBooks.includes(b) && (searchTerm === '' || b.toLowerCase().includes(searchTerm)),
      );
    }

    if (filteredBooks.length === 0) {
      $resultsContainer.html('<div class="add-worldbook-no-results">没有找到匹配的世界书</div>').show();
      return;
    }

    const action = isCharacterSearch ? 'replace-character-lorebook' : 'pin-global-lorebook';
    const resultsHtml = filteredBooks
      .slice(0, 100)
      .map(
        name => `
          <div class="add-worldbook-result-item" data-action="${action}" data-lorebook-name="${name}">
              ${name}
          </div>
      `,
      )
      .join('');
    $resultsContainer.html(resultsHtml).show();
  }, 300);

  $panel.on('focus', '#add-worldbook-search-input, #character-worldbook-search-input', function () {
    const $input = $(this);
    const searchTerm = $input.val().toLowerCase();
    debounceSearch(searchTerm, $input);
  });

  $panel.on('input', '#add-worldbook-search-input, #character-worldbook-search-input', function () {
    const $input = $(this);
    const searchTerm = $input.val().toLowerCase();
    debounceSearch(searchTerm, $input);
  });

  $panel.on('blur', '#add-worldbook-search-input, #character-worldbook-search-input', function () {
    const $input = $(this);
    setTimeout(() => {
      debounceSearch(null, $input);
    }, 200);
  });

  // 点击外部隐藏结果
  $(parentDoc).on('click', function (e) {
    if (!$(e.target).closest('.global-lorebook-adder').length) {
      $('.add-worldbook-results', parentDoc).hide();
    }
  });

  const debouncedFilter = _.debounce((lorebookName, searchText, isGlobal) => {
    const clusterize = virtualScrollers[lorebookName];
    if (!clusterize) return;

    const allEntries = allEntriesData[lorebookName] || [];
    const lowerSearchText = searchText.toLowerCase().trim();

    const matchedEntries = !lowerSearchText
      ? allEntries
      : allEntries.filter(
          entry =>
            (entry.name || '').toLowerCase().includes(lowerSearchText) ||
            (entry.content || '').toLowerCase().includes(lowerSearchText) ||
            (Array.isArray(entry.strategy?.keys) &&
              entry.strategy.keys.join(',').toLowerCase().includes(lowerSearchText)),
        );

    // 更新搜索结果到 filteredEntriesData 状态
    if (!lowerSearchText) {
      // 如果搜索框为空，清空搜索结果
      clearFilteredEntries(lorebookName);
    } else {
      // 如果有搜索内容，保存搜索结果
      setFilteredEntries(lorebookName, matchedEntries);
    }

    const newRows = matchedEntries.map(entry => `<li>${createEntryHtml(entry, lorebookName)}</li>`);

    clusterize.update(newRows);

    setTimeout(() => updateHeaderCheckboxState(lorebookName, isGlobal), 50);
  }, 300);

  $panel
    .off('input.search keydown.search')
    .on('input.search', '.lorebook-search-input', function () {
      const $input = $(this);
      const searchText = $input.val();
      const lorebookName = $input.attr('data-lorebook-name');
      const isGlobal = $input.data('is-global');
      debouncedFilter(lorebookName, searchText, isGlobal);
    })
    .on('keydown.search', '.lorebook-search-input', function (e) {
      if (e.key === 'Escape') {
        $(this).val('').trigger('input.search');
      }
    });

  // 移动端关键字输入优化：点击关键字输入框时展开为一整行
  if (isMobile()) {
    $panel.on('focus', '.keywords-input, .secondary-keywords-input', function () {
      const $input = $(this);
      const $keywordsArea = $input.closest('.keywords-edit-area');
      const $keywordGroup = $input.closest('.keyword-group');

      // 添加聚焦状态类
      $keywordsArea.addClass('keyword-focused');
      // 标记当前聚焦的关键字组
      $keywordGroup.addClass('focused');
    });

    $panel.on('blur', '.keywords-input, .secondary-keywords-input', function () {
      const $input = $(this);
      const $keywordsArea = $input.closest('.keywords-edit-area');

      // 短暂延迟后移除聚焦状态，以防止在两个输入框之间切换时的闪烁
      setTimeout(() => {
        // 检查是否有其他关键字输入框正在聚焦
        const hasOtherFocused = $keywordsArea.find('.keywords-input:focus, .secondary-keywords-input:focus').length > 0;
        if (!hasOtherFocused) {
          $keywordsArea.removeClass('keyword-focused');
          // 移除所有关键字组的focused类
          $keywordsArea.find('.keyword-group').removeClass('focused');
        }
      }, 100);
    });
  }
}
